import { useEffect } from 'react';
import { create } from 'zustand';
import { useStore } from '../store/useStore';

/**
 * Translation by English source text: t("Find my plan") looks up the string in the
 * selected language and falls back to English. Dictionaries live in ./locales/<code>.json:
 *   - ui.<code>.json  : hand-translated menus and buttons (committed)
 *   - <code>.json     : everything else, generated by `npm run translate` (AI, cached)
 * Placeholders like {n} are filled from the second argument.
 */
export const LANGS = [
  { code: 'en', label: 'English', short: 'EN' },
  { code: 'es', label: 'Español', short: 'ES' },
  { code: 'vi', label: 'Tiếng Việt', short: 'VI' },
  { code: 'zh', label: '中文', short: '中文' },
  { code: 'fr', label: 'Français', short: 'FR' },
  { code: 'ar', label: 'العربية', short: 'ع', dir: 'rtl' },
];

const loaders = import.meta.glob('./locales/*.json');
const useDicts = create(() => ({}));

async function loadLang(code) {
  if (code === 'en' || useDicts.getState()[code]) return;
  const parts = await Promise.all(
    [`./locales/ui.${code}.json`, `./locales/${code}.json`]
      .filter((p) => loaders[p])
      .map((p) => loaders[p]().then((m) => m.default)),
  );
  useDicts.setState({ [code]: Object.assign({}, ...parts) });
}

function interpolate(str, vars) {
  if (!vars) return str;
  return str.replace(/\{(\w+)\}/g, (m, k) => (vars[k] ?? m));
}

export function useT() {
  const lang = useStore((s) => s.lang) || 'en';
  const dict = useDicts((s) => s[lang]);
  return (text, vars) => {
    if (typeof text !== 'string') return text;
    const translated = (lang !== 'en' && dict?.[text]) || text;
    return interpolate(translated, vars);
  };
}

/** True when the current language has no AI-generated dictionary yet. */
export function useTranslationPending() {
  const lang = useStore((s) => s.lang) || 'en';
  return lang !== 'en' && !loaders[`./locales/${lang}.json`];
}

const FONT_URLS = {
  zh: 'https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;600;800&family=Noto+Serif+SC:wght@600;800&display=swap',
  ar: 'https://fonts.googleapis.com/css2?family=Noto+Kufi+Arabic:wght@600;800&family=Noto+Naskh+Arabic:wght@400;600&display=swap',
};

/** Keeps <html lang/dir>, script fonts, and dictionaries in sync with the chosen language. */
export function useLanguageEffects() {
  const lang = useStore((s) => s.lang) || 'en';
  useEffect(() => {
    const meta = LANGS.find((l) => l.code === lang) || LANGS[0];
    document.documentElement.lang = lang === 'zh' ? 'zh-Hans' : lang;
    document.documentElement.dir = meta.dir || 'ltr';
    if (FONT_URLS[lang] && !document.getElementById(`font-${lang}`)) {
      const link = document.createElement('link');
      link.id = `font-${lang}`;
      link.rel = 'stylesheet';
      link.href = FONT_URLS[lang];
      document.head.appendChild(link);
    }
    loadLang(lang);
  }, [lang]);
}
